correct_fix:
S_MAIN_YELLOW: begin
    if (timer_cnt == TICKS_YELLOW - 1'b1) begin
        current_state <= S_SIDE_GREEN;
        timer_cnt     <= 4'd0;
    end else begin

S_SIDE_GREEN: begin
    if (!car_present || (timer_cnt == TICKS_GREEN - 1'b1)) begin
        current_state <= S_SIDE_YELLOW;
        timer_cnt     <= 4'd0;
    end else begin

S_MAIN_GREEN: begin
    if (timer_cnt < TICKS_GREEN - 1'b1) begin
        timer_cnt <= timer_cnt + 1'b1;
    end else if (car_present) begin
        current_state <= S_MAIN_YELLOW;
        timer_cnt     <= 4'd0;
    end
end

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        val_out <= {WIDTH_BITS{1'b0}};

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        current_state <= S_MAIN_GREEN;
        timer_cnt     <= 4'd0;

if (do_push) begin
    mem[wr_ptr] <= data_in;
    wr_ptr      <= wr_ptr + 1'b1;
end

3'b000: begin // ADD
    {flag_carry, alu_res} = src_a + src_b;
end

if (do_push) begin
    mem[wr_ptr] <= data_in;
    wr_ptr      <= wr_ptr + 1'b1;
end

S_MAIN_YELLOW: begin
    if (timer_cnt == TICKS_YELLOW - 1'b1) begin
        current_state <= S_SIDE_GREEN;
        timer_cnt     <= 4'd0;
    end else begin

    3'b100: begin // XOR
        alu_res    = src_a ^ src_b;
        flag_carry = 1'b0;
    end
    default: begin // Safe fallback
        alu_res    = {DATA_WIDTH{1'b0}};
        flag_carry = 1'b0;
    end
endcase

case ({do_push, do_pop})
    2'b10: item_count <= item_count + 1'b1;
    2'b01: item_count <= item_count - 1'b1;
    default: item_count <= item_count;
endcase

if (val_out >= limit_val) begin
    val_out <= {WIDTH_BITS{1'b0}};
end else begin

S_MAIN_YELLOW: begin
    if (timer_cnt == TICKS_YELLOW - 1'b1) begin
        current_state <= S_SIDE_GREEN;
        timer_cnt     <= 4'd0;

3'b001: begin // SUB (flag_carry is borrow)
    alu_res    = src_a - src_b;
    flag_carry = (src_a < src_b);
end
